import { Badge, Button, Link, Table, TableBody, TableCaption, TableCell, TableHead, TableHeader, TableRow, cn, type BadgeTone } from '@gntik-ai/ui';
import { Download } from '@gntik-ai/icons';
import { formatMoney, formatShortDate, type DateInput } from '../format';
import { sampleInvoices } from './fixtures';

export type InvoiceStatus = 'paid' | 'open' | 'overdue' | 'void' | 'draft';

export interface Invoice {
  id: string;
  /** Human invoice number, e.g. "INV-2026-0004". */
  number: string;
  /** Issue date. */
  date: DateInput;
  amount: number;
  /** ISO 4217 code. Default: the table's currency. */
  currency?: string;
  status: InvoiceStatus;
  /** PDF URL. Without it the download control calls `onDownload` only. */
  url?: string;
}

export interface InvoiceTableProps {
  invoices?: Invoice[];
  /** Table caption (screen-reader only unless `showCaption`). */
  caption?: string;
  showCaption?: boolean;
  currency?: string;
  /** Called when a download control is activated. */
  onDownload?: (invoice: Invoice) => void;
  /** Row density. */
  density?: 'compact' | 'comfortable';
  className?: string;
}

const STATUS: Record<InvoiceStatus, { label: string; tone: BadgeTone }> = {
  paid: { label: 'Paid', tone: 'success' },
  open: { label: 'Due', tone: 'warning' },
  overdue: { label: 'Overdue', tone: 'destructive' },
  void: { label: 'Void', tone: 'neutral' },
  draft: { label: 'Draft', tone: 'neutral' },
};

/** Invoice history: number, date, amount, status and a per-row PDF download. */
export function InvoiceTable({
  invoices = sampleInvoices,
  caption = 'Invoice history',
  showCaption = false,
  currency = 'USD',
  onDownload,
  density = 'comfortable',
  className,
}: InvoiceTableProps) {
  return (
    <div className={cn('overflow-hidden rounded-lg border border-border bg-card', className)}>
      <Table density={density}>
        <TableCaption srOnly={!showCaption}>{caption}</TableCaption>
        <TableHeader>
          <TableRow>
            <TableHead>Invoice</TableHead>
            <TableHead>Date</TableHead>
            <TableHead>Status</TableHead>
            <TableHead align="right">Amount</TableHead>
            <TableHead align="right">
              <span className="sr-only">Download</span>
            </TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {invoices.map((inv) => {
            const status = STATUS[inv.status];
            const label = `Download ${inv.number}`;
            return (
              <TableRow key={inv.id}>
                <TableCell className="font-mono text-[12.5px] font-medium text-foreground">{inv.number}</TableCell>
                <TableCell className="whitespace-nowrap text-muted-foreground">{formatShortDate(inv.date)}</TableCell>
                <TableCell>
                  <Badge tone={status.tone} dot>
                    {status.label}
                  </Badge>
                </TableCell>
                <TableCell align="right" className="font-mono tabular-nums text-foreground">
                  {formatMoney(inv.amount, inv.currency ?? currency)}
                </TableCell>
                <TableCell align="right">
                  {inv.url ? (
                    <Link
                      href={inv.url}
                      download
                      aria-label={label}
                      onClick={() => onDownload?.(inv)}
                      className="inline-flex items-center gap-1.5 text-[12.5px] font-semibold"
                    >
                      <Download size={14} aria-hidden />
                      PDF
                    </Link>
                  ) : onDownload && inv.status !== 'void' && inv.status !== 'draft' ? (
                    <Button variant="ghost" size="sm" icon={Download} aria-label={label} onClick={() => onDownload(inv)}>
                      PDF
                    </Button>
                  ) : (
                    <span className="text-[12px] text-muted-foreground">—</span>
                  )}
                </TableCell>
              </TableRow>
            );
          })}
        </TableBody>
      </Table>
    </div>
  );
}

import type { Invoice } from './InvoiceTable';

/** Sample invoice history. */
export const sampleInvoices: Invoice[] = [
  { id: 'inv_0526', number: 'INV-2026-0005', date: '2026-06-01', amount: 1620, status: 'open', url: '#invoice-INV-2026-0005' },
  { id: 'inv_0426', number: 'INV-2026-0004', date: '2026-05-01', amount: 1584.2, status: 'paid', url: '#invoice-INV-2026-0004' },
  { id: 'inv_0326', number: 'INV-2026-0003', date: '2026-04-01', amount: 1498, status: 'paid', url: '#invoice-INV-2026-0003' },
  { id: 'inv_0226', number: 'INV-2026-0002', date: '2026-03-01', amount: 1432.6, status: 'overdue', url: '#invoice-INV-2026-0002' },
  { id: 'inv_0126', number: 'INV-2026-0001', date: '2026-02-01', amount: 1200, status: 'void' },
];

/** Shared formatting for the billing blocks (en-US, Intl). */

/** A calendar date: a `Date` or an ISO `YYYY-MM-DD` string (read as a local date, no UTC shift). */
export type DateInput = Date | string;

export function toDate(value: DateInput): Date {
  if (value instanceof Date) return value;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return new Date(value);
}

const dateFmt = new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
const shortDateFmt = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

/** "June 1, 2026". */
export function formatDate(value: DateInput): string {
  return dateFmt.format(toDate(value));
}

/** "Jun 1, 2026". */
export function formatShortDate(value: DateInput): string {
  return shortDateFmt.format(toDate(value));
}

/** Money with the currency symbol: "$1,620.00" (or no decimals with `whole`). */
export function formatMoney(amount: number, currency = 'USD', whole = false): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: whole ? 0 : 2,
    maximumFractionDigits: whole ? 0 : 2,
  }).format(amount);
}

/** Grouped number, compact above a million: "412,800", "78.4M". */
export function formatQuantity(value: number): string {
  if (Math.abs(value) >= 1_000_000) {
    return new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 }).format(value);
  }
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format(value);
}
